    last_modify_user varchar(64)
        constraint fksj00krnc5ryrwjnegvkf0uvfr
            references public."user",
    create_user      varchar(255)
        constraint fk81pjr0s0jthybgpu4jwj8es9b
            references public."user",
    publish_at       timestamp,
    primary key (sample, service),
    constraint fkdavk4auxqaf0uaup07px1wisd
        foreign key (sample, service) references public.request
);

