INSERT INTO panel.interpretation (sample, service, value, create_at, last_modify_at, last_modify_user, create_user, publish_at) VALUES (202210279400004, 'N003', '{"result": "POSITIVE", "checker1": "이새미", "checker2": "설창안", "comment1": "", "comment2": "", "coverage": "99.4", "variants": [{"snv": "hg19:02:225376215:G:A", "gene": "CUL3", "class": "PV", "hgvsc": "c.739C>T", "hgvsp": "p.Arg247Ter", "disease": "NDWOWAOS, PTI", "analysis": "497ff234-fe85-4328-9d1e-55debae35193:22GMD065:008", "zygosity": "Het", "inheritance": "AD"}, {"snv": "hg19:22:041572254:T:G", "gene": "EP300", "class": "PV", "hgvsc": "c.4783T>G", "hgvsp": "p.Phe1595Val", "disease": "MHS2, RTS2", "analysis": "497ff234-fe85-4328-9d1e-55debae35193:22GMD065:008", "zygosity": "Het", "inheritance": "AD"}], "mean_depth": "317.66", "result_text": "의뢰 사유와 관련된 변이가 발견되었습니다.", "abbreviation": "AD, Autosomal dominant; Het, Heterozygous; PV, Pathogenic Variant", "interpretation": "[2022.11.17]\nDES 분석 결과, CUL3, EP300 유전자에서 Pathogenic Variant (PV)가 발견되었습니다.\n\nCUL3 유전자의 c.739C>T (p.Arg247Ter) 변이는 일반 인구집단(gnomAD, KRGDB)에서 보고된 바 없는 매우 드문 변이입니다. 이 변이는 Neurodevelopmental disorder 환자에서 보고된 바 있으며(PMID: 33004838), ClinVar에서 single submitter에 의해 Pathogenic으로 분류되어 있습니다(ID: 523862).\nCUL3 유전자는 Neurodevelopmental disorder with or without autism or seizures, Pseudohypoaldosteronism, type IIE 관련 유전자로 상염색체 우성 유전 양상을 보입니다. Neurodevelopmental disorder with or without autism or seizures는 유아기에 명백한 전반적인 발달 지연, 지적 발달 장애 및 언어 지연을 특징으로 합니다. 일부 환자는 발작을 일으키고 발작이 시작된 후 퇴행을 보일 수 있습니다. 다른 사람들은 자폐증 특징이나 행동 이상을 가지고 있습니다. cardiac defects, failure to thrive 또는 brain imaging anomalies과 같은 추가적인 이상을 보일 수 있습니다. \n\nEP300 유전자의 c.4783T>G (p.Phe1595Val) 변이는 일반 인구집단(gnomAD, KRGDB)에서 보고된 바 없는 매우 드문 변이로, in-silico prediction (SIFT, PolyPhen, MutationTaster)에서는 Deleterious로 예측되었습니다. 이 변이는 ClinVar에서 Pathogenic/Likely Pathogenic으로 분류되어 있으며(ID: 372363), 기존에 Rubinstein-Taybi syndrome 환자에서 보고된 바 있습니다(PMID: 26633542, 27465822, 29133209, 31036916, 31785789, 31137009).\nEP300 유전자는 Menke-Hennekam syndrome 2, Rubinstein-Taybi syndrome 2 관련 유전자로 상염색체 우성 유전 양상을 보입니다. Rubinstein-Taybi syndrome은 distinctive facial features, broad and often angulated thumbs and halluces, short stature, moderate-to-severe intellectual disability를 특징으로 합니다. 특징적인 두개안면의 특징은 downslanted palpebral fissures, low-hanging columella, high palate, grimacing smile, talon cusps입니다. 태아기의 성장은 종종 정상이며, 키, 체중, 머리 둘레 백분위수는 생후 첫 몇 개월 동안 급격히 떨어집니다. 작은 키가 성인기에 전형적으로 나타나며, 비만은 아동기 또는 청소년기에 발생할 수 있습니다. 평균 IQ 범위는 35에서 50 사이입니다. 그러나 발달 결과는 상당히 다양합니다. 추가적인 이상소견으로 ocular abnormalities, hearing loss, respiratory difficulties, congenital heart defects, renal abnormalities, cryptorchidism, feeding problems, recurrent infections, severe constipation 등이 있습니다. Menke-Hennekam syndrom은 developmental delay, growth retardation, craniofacial dysmorphism 특징을 보이며, intellectual disability of variable severity, speech delay, autistic behavior, short stature, microcephaly 등의 임상 양상을 보입니다. 얼굴 기형은 short palpebral fissures, telecanthi, depressed nasal ridge, short nose, anteverted nares, short columella, long philtrum 등이 있습니다.\n\nClinical correlation 및 가족검사가 권장됩니다.", "incidental_findings": {"variants": [], "result_text": "", "abbreviation": "", "interpretation": "ACMG에서 권고한 78개 유전자에서 (Likely) Pathogenic Variant는 발견되지 않았습니다.", "abbreviation_disease": "", "abbreviation_reference": ""}, "reason_for_referral": "1. 질환 발생 연령: 1세\n2. 임상 정보: learning disability, mental retardation, motore delay, speech delay\n3. 진단: DD/ID, R/O autism spectrum disorder(familial)-proband 검사 후 여동생 DNA 가족검사 의뢰 예정, speech delay\n4. 가족력: 여동생-발달지연, 자폐스펙트럼", "abbreviation_disease": "NDWOWAOS, Neurodevelopmental disorder with or without autism or seizures; PTI, Pseudohypoaldosteronism, type IIE; MHS2, Menke-Hennekam syndrome 2; RTS2, Rubinstein-Taybi syndrome 2", "abbreviation_reference": "NM_003590.5(CUL3); NM_001429.4(EP300)", "consent_incidental_findings": true}', '2022-11-17 13:31:11.219869', '2022-11-17 13:39:38.832449', '218903', '218903', '2022-11-17 13:39:38.822571');
