insert into panel.interpretation (sample, service, value, create_at, last_modify_at, last_modify_user, create_user, publish_at)
values  (202211299223502, 'N003', '{"result": "INCONCLUSIVE", "checker1": "이새미", "checker2": "설창안", "comment1": "", "comment2": "", "coverage": "99.5", "variants": [{"snv": "hg19:04:001941428:C:T", "gene": "NSD2", "class": "VUS", "hgvsc": "c.1804C>T", "hgvsp": "p.Arg602Trp", "disease": "RSS", "analysis": "497ff234-fe85-4328-9d1e-55debae35193:22GMD069:006", "zygosity": "Het", "inheritance": "AD"}], "mean_depth": "393.99", "result_text": "의뢰 사유와 관련 가능성이 불분명한 변이가 발견되었습니다.", "abbreviation": "AD, Autosomal dominant; Het, Heterozygous; VUS, Variant of Uncertain Significance", "interpretation": "[2022.12.23]\nDES 분석 결과, NSD2 유전자에서 Variant of Uncertain Significance (VUS)가 발견되었습니다.\n\nNSD2 유전자의 c.1804C>T (p.Arg602Trp) 변이는 일반 인구집단(gnomAD, KRGDB)에서 보고된 바 없는 매우 드문 변이로, in-silico prediction (SIFT, PolyPhen, MutationTaster)에서는 Deleterious로 예측되었습니다.\nNSD2 유전자는 Rauch-Steindl syndrome 관련 유전자로 상염색체 우성 유전 양상을 보입니다. Rauch-Steindl syndrome은 poor pre- and postnatal growth, short stature and small head circumference, characteristic dysmorphic facial features, variable developmental delay with delayed motor and speech acquisition and impaired intellectual function 등의 임상 양상을 보이며 포현형은 매우 다양합니다. \n\n의뢰 사유와 다소 차이가 있으므로 Clinical correlation 및 필요하다고 판단될 경우 가족검사가 권장됩니다.", "incidental_findings": {"variants": [], "result_text": "", "abbreviation": "", "interpretation": "ACMG에서 권고한 78개 유전자에서 (Likely) Pathogenic Variant는 발견되지 않았습니다.", "abbreviation_disease": "", "abbreviation_reference": ""}, "reason_for_referral": "webbed neck", "abbreviation_disease": "RSS, Rauch-Steindl syndrome", "abbreviation_reference": "NM_133330.3(NSD2)", "consent_incidental_findings": true}', '2022-12-23 17:02:28.931480', '2022-12-23 17:02:52.244488', '218903', '218903', '2022-12-23 17:02:52.226060');
